      if (!evidence || !payment || !completed) return null;
      matched = /^已支付\s*([¥￥]\s*[0-9][0-9,.]*)$/.exec(title);
      if (!matched) return null;
      money = common.displayed(matched[1]);
      if (!money || common.displayed(payment[2]) !== money) return null;
